{"op":"add","path":"/elements/price-metric","value":{"type":"Stat","props":{"label":"Price","value":{"$template":"$${price}"}},"children":[]}}
{"op":"add","path":"/elements/weight-metric","value":{"type":"Stat","props":{"label":"Weight","value":{"$template":"${weightKg} kg"}},"children":[]}}
{"op":"add","path":"/elements/battery-metric","value":{"type":"Stat","props":{"label":"Battery","value":{"$template":"${batteryH} hrs"}},"children":[]}}
{"op":"add","path":"/elements/rating-metric","value":{"type":"Stat","props":{"label":"Rating","value":{"$template":"${rating} / 5"},"change":{"$template":"${reviews} reviews"},"trend":"up"},"children":[]}}
