{"op":"add","path":"/elements/laptop-detail-card","value":{"type":"Card","props":{"title":{"$item":"name"}},"children":["detail-content"]}}
{"op":"add","path":"/elements/detail-content","value":{"type":"Stack","props":{"direction":"vertical","gap":"md"},"children":["specs-heading","specs-list","ports-heading","ports-list","pros-heading","pros-list","cons-heading","cons-list","best-for-text"]}}
{"op":"add","path":"/elements/specs-heading","value":{"type":"Heading","props":{"text":"Specifications","level":"h4"},"children":[]}}
