{"op":"add","path":"/elements/cpu-text","value":{"type":"Text","props":{"text":{"$template":"CPU: ${cpu}"},"variant":"body"},"children":[]}}
{"op":"add","path":"/elements/ram-text","value":{"type":"Text","props":{"text":{"$template":"RAM: ${ramGb}GB"},"variant":"body"},"children":[]}}
